#!/bin/sh
# Builds Zajil's engine for the app (ADR-0012): crates/zajil-android as
# libzajil_android.so for arm64-v8a (Android 8.0, API 26, and later), and
# its Kotlin bindings, generated by UniFFI from the library itself.
#
#   build-engine.sh <jniLibs folder> <Kotlin folder>
#
# Gradle runs it before every build (the BuildEngine task in
# app/build.gradle.kts), with ANDROID_NDK_HOME set to its NDK. Always a
# release build of the engine: the debug one is ten times the size.
set -eu

jni_libs=$1
kotlin=$2
root=$(cd "$(dirname "$0")/.." && pwd)
PATH="$HOME/.cargo/bin:$PATH"
cd "$root"

cargo ndk --target arm64-v8a --platform 26 --output-dir "$jni_libs" \
    build --release --package zajil-android

# The bindings come from the host's build of the same crate.
cargo build --package zajil-android --features bindgen --bin uniffi-bindgen
case "$(uname -s)" in
    Darwin) host_lib=target/debug/libzajil_android.dylib ;;
    *) host_lib=target/debug/libzajil_android.so ;;
esac
cargo build --package zajil-android --lib
rm -rf "$kotlin"
target/debug/uniffi-bindgen generate --library "$host_lib" --language kotlin \
    --no-format --out-dir "$kotlin"
